// 본인의 Hugging Face Space URL 입력
const BACKEND_URL = window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1' 
    ? 'http://localhost:7860/' 
    : 'https://uzaramen108-paper-backend.hf.space/'; 

let isLoginMode = true;

const authTitle_signin = document.getElementById("auth-title-signin");
const authTitle_signup = document.getElementById("auth-title-signup");
const submitBtn_signin = document.getElementById("submit-btn-signin");
const submitBtn_signup = document.getElementById("submit-btn-signup");
const toggleModeBtn_signin = document.getElementById("toggle-mode-btn-signin");
const toggleModeBtn_signup = document.getElementById("toggle-mode-btn-signup");
const authForm = document.getElementById("auth-form");
const nicknameInput = document.getElementById("nickname");
const passwordInput = document.getElementById("password");

// 💡 공통 모드 토글 함수
function toggleAuthMode() {
    isLoginMode = !isLoginMode;
    
    if (isLoginMode) {
        // 로그인 모드 활성화 (회원가입 숨김)
        authTitle_signin.classList.remove("hidden");
        submitBtn_signin.classList.remove("hidden");
        toggleModeBtn_signin.classList.remove("hidden");
        
        authTitle_signup.classList.add("hidden");
        submitBtn_signup.classList.add("hidden");
        toggleModeBtn_signup.classList.add("hidden");
    } else {
        // 회원가입 모드 활성화 (로그인 숨김)
        authTitle_signin.classList.add("hidden");
        submitBtn_signin.classList.add("hidden");
        toggleModeBtn_signin.classList.add("hidden");
        
        authTitle_signup.classList.remove("hidden");
        submitBtn_signup.classList.remove("hidden");
        toggleModeBtn_signup.classList.remove("hidden");
    }
}

// 💡 양쪽 토글 버튼에 모두 이벤트를 달아줍니다!
toggleModeBtn_signin.addEventListener("click", toggleAuthMode);
toggleModeBtn_signup.addEventListener("click", toggleAuthMode);

authForm.addEventListener("submit", async (e) => {
    e.preventDefault();
    const nickname = nicknameInput.value.trim();
    const password = passwordInput.value.trim();

    if (!nickname || !password) return;

    const submitBtn = isLoginMode ? submitBtn_signin : submitBtn_signup;
    const originalText = submitBtn.textContent; // "로그인" 또는 "회원가입" 기억
    
    submitBtn.disabled = true;
    submitBtn.textContent = "처리 중...";

    const endpoint = isLoginMode ? "api/login" : "api/signup";

    try {
        const response = await fetch(`${BACKEND_URL}${endpoint}`, {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ nickname, password })
        });

        const result = await response.json();

        if (response.ok) {
            if (isLoginMode) {
                // 로그인 성공 시 로컬 스토리지에 닉네임 저장
                localStorage.setItem("currentUser", result.nickname);
                alert(`${result.nickname}님, 환영합니다!`);
                window.location.href = "../index.html"; 
            } else {
                alert("회원가입이 완료되었습니다. 로그인해주세요.");
                // 💡 가입 성공 시 자동으로 로그인 화면으로 돌려보냄
                toggleAuthMode();
                passwordInput.value = ""; // 비밀번호 칸 비워주기
            }
        } else {
            alert(`오류: ${result.detail}`);
        }
    } catch (error) {
        alert("서버와 통신할 수 없습니다. 잠시 후 다시 시도해주세요.");
    } finally {
        submitBtn.disabled = false;
        submitBtn.textContent = originalText;
    }
});